package cl.dynasty.nexusbeacon.platform.classic;
import java.util.UUID;import org.bukkit.Material;import org.bukkit.block.Block;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.EventPriority;import org.bukkit.event.Listener;import org.bukkit.event.block.Action;import org.bukkit.event.block.BlockBreakEvent;import org.bukkit.event.player.PlayerInteractEvent;
final class ClassicBaseProtectionListener implements Listener {private final ClassicApplicationState state;private final boolean protect,ownerOnlyInteract;private final int layers;ClassicBaseProtectionListener(ClassicApplicationState state,boolean protect,boolean ownerOnlyInteract,int layers){this.state=state;this.protect=protect;this.ownerOnlyInteract=ownerOnlyInteract;this.layers=Math.max(1,layers);}@EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false)public void breakBase(BlockBreakEvent event){Block block=event.getBlock();if(!protect||block==null||block.getType()==Material.BEACON)return;ClassicBeaconRecord record=find(block);if(record!=null&&!authorized(event.getPlayer(),record))event.setCancelled(true);}@EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void interactBase(PlayerInteractEvent event){if(!protect||!ownerOnlyInteract||event.getAction()!=Action.RIGHT_CLICK_BLOCK||event.getClickedBlock()==null||event.getClickedBlock().getType()==Material.BEACON)return;ClassicBeaconRecord record=find(event.getClickedBlock());if(record!=null&&!authorized(event.getPlayer(),record))event.setCancelled(true);}ClassicBeaconRecord find(Block block){String world=block.getWorld().getName();for(int layer=1;layer<=layers;layer++){int y=block.getY()+layer;for(int x=block.getX()-layer;x<=block.getX()+layer;x++)for(int z=block.getZ()-layer;z<=block.getZ()+layer;z++){ClassicBeaconRecord record=state.find(new ClassicBeaconLocation(world,x,y,z));if(record!=null&&record.isProtectBase())return record;}}return null;}static boolean authorized(Player player,ClassicBeaconRecord record){UUID id=player.getUniqueId();return id.equals(record.getOwner())||record.getTrusted().contains(id)||player.hasPermission("NexusBeacon.admin");}}
